schema:
CREATE TABLE ITP (
    ITEMN INT,
    PONUM INT
);
CREATE TABLE ITM (
    ITEMN INT,
    TYPE INT,
    PRIMARY KEY (ITEMN)
);
CREATE TABLE PUR (
    PONUM INT,
    ODATE INT,
    VENDN INT
);

counterexample:
INSERT INTO ITM (ITEMN, TYPE) VALUES (2, 1);
INSERT INTO ITM (ITEMN, TYPE) VALUES (2, 2);
INSERT INTO ITP (ITEMN, PONUM) VALUES (2, 100);
INSERT INTO PUR (PONUM, ODATE, VENDN) VALUES (100, 90, 500);

