);

CREATE TABLE DEPTS (
    DNAME INTEGER,
    DPROJ INTEGER
);
CREATE TABLE PAYROLL (
    EMPL  INTEGER PRIMARY KEY,
    PDEPT INTEGER
);
CREATE TABLE TEAMS (
    TMEMBER INTEGER,
    TPROJ   INTEGER,
    FOREIGN KEY (TMEMBER) REFERENCES PAYROLL(EMPL)
);

